/* SPDX-License-Identifier: LGPL-2.1-or-later */

#include <string.h>

#include "alloc-util.h"
#include "strv.h"
#include "tests.h"

TEST(rebreak_lines_truncated_utf8_lead_byte) {
        /* A truncated multi-byte lead byte right before the terminating NUL must not make the scan step
         * past the NUL. Use an exactly sized heap buffer so that ASan/valgrind notice an over-read. */
        _cleanup_free_ char *s = memdup("foo\xF0", 5);
        ASSERT_NOT_NULL(s);

        char *l[] = { s, NULL };
        _cleanup_strv_free_ char **broken = NULL;

        ASSERT_OK(strv_rebreak_lines(l, 80, &broken));
        ASSERT_NOT_NULL(broken);
        ASSERT_EQ(strv_length(broken), 1u);
        ASSERT_EQ(strlen(broken[0]), 4u);
        ASSERT_EQ(memcmp(broken[0], "foo\xF0", 5), 0);
}

DEFINE_TEST_MAIN(LOG_DEBUG);

